/* ==== data/kronoloji_habsburg.js ==== */
// =====================================================================
// HABSBURG AVUSTURYA — DEVLET KRONOLOJİSİ (pilot, 20 Ağustos 2026)
// =====================================================================
// ⚠️ HENÜZ CANLI DEĞİL. `index.html`e ve `arac/girdi.py`ye bağlanmadı;
//    `data/devletler.js`teki `habsburg` künyesiyle birleştirmeyi
//    koordinatör yapar. Bu dosya `devletler.js`e DOKUNMAZ.
//
// ── NİÇİN VAR — Emre'nin beyanı ──────────────────────────────────────
// "Diğer devletlerin kronolojilerini o devletlerin muteber akademik
//  kaynaklarını karıştırarak, O DEVLETİN O MİLLETİN ÖNEM VERDİĞİ ŞEKİLDE
//  oluşturalım. Osmanlı devletine benzer detayda olsun."
//
// 🔴 ÖLÇÜLEN BAŞLANGIÇ NOKTASI — ve işin asıl kalemi buydu:
//    `devletler.js:habsburg` kronolojisi  14 madde
//    14'ün 8'i OSMANLI CEPHESİ           (Viyana ×2 · Budin · Zitvatorok ·
//                                         Karlofça · Pasarofça · Belgrad · 1683)
//    Avusturya'nın KENDİ ulusal anlatısının dönüm noktalarından
//    hiçbiri YOKTU: Beyaz Dağ 1620 · Vestfalya 1648 · Pragmatik Yaptırım
//    1713 · Silezya'nın kaybı · Viyana Kongresi 1815 · 1848 · Königgrätz 1866.
//    ⇒ Osmanlı arşivinden bakılmış bir Habsburg kronolojisiydi. Emre'nin
//      istediği tam bunun tersi.
//
// ── ÖNEM SKALASI — sınanabilirlik kuralı ─────────────────────────────
// `onem:5` verilen HER maddede, o maddeyi "dönüm noktası" sayan kaynağın
// kendi ifadesi `kaynak:` alanında ya da `d:` metninde geçer. Kendi
// sezgimle 5 vermedim.
// 🔴 VE BU KURAL BİR MADDEYİ DÜŞÜRDÜ: 1687 Pressburg Diyeti'ne önce 5
//    vermiştim; okunan kaynak, Macar tacının kalıtsal kabulünü 1687'ye
//    değil 1699 SONRASINA yerleştiriyordu. Hem ifade hem önem geri
//    çekildi (5 → 4). Ölçüt sınanabilir olunca kendi maddemi çürüttü.
// ⚠️ Ve bu başlık bir kez YANLIŞ SAYI taşıdı: "5'lik madde: 15" yazıyordu,
//    ölçüm 22 dedi. Sayı elle yazılmıştı; artık ölçülerek yazılıyor.
//   5 Avusturya ulusal anlatısında dönüm noktası
//   4 hanedanı, sınırı ya da rejimi değiştiren
//   3 önemli ama dönüm değil · 2 yerel/kurumsal · 1 ayrıntı
//
// ── `dunya` ALANI — M-0873 kesin şeması, 20 Ağustos ──────────────────
// İki puan var ve karıştırılmaz:
//   `onem`  BU DOSYANIN DEVLETİ (Habsburg) için ağırlık — dosyadan dosyaya DEĞİŞİR
//   `dunya` OLAYIN kendisine ait — her dosyada AYNI olmak ZORUNDA
// Ölçüm: 107/107 maddeye eklendi · dağılım 5=7 · 4=24 · 3=21 · 2=33 · 1=22
//
// 🔴 BU DOSYA `dunya` YAZAN İLK DOSYA — ölçüldü: `kronoloji_lehistan.js` ve
//    `kronoloji_rusya.js`te alan HENÜZ YOK. ⇒ Aşağıdaki değerler ötekiler
//    için fiilen REFERANS olacak. Paylaşılan olayların listesi teslim
//    raporunda ayrıca verildi ki başka dosyalar hizalanabilsin;
//    "aynı olay farklı `dunya`" M-0873'e göre KUSURDUR.
//
// `dunya:5` verilen yedi maddenin gerekçesi (M-0873 çapaları + kaynak):
//   1526-08-29  bir krallık yıkıldı, üç taç dört yüz yıl tek hanedanda birleşti
//   1648-10-24  M-0873 çapa listesinde
//   1683-09-12  M-0873 çapa listesinde
//   1806-08-06  844 yıllık kurum sona erdi (Die Welt der Habsburger)
//   1815-06-09  M-0873 çapası "1815" — Nihaî Sened'e verildi
//   1914-07-28  M-0873 çapası "1914" — savaş İLANINA verildi
//   1918-11-11  dört imparatorluğun çözülmesi
// ⚠️ İKİ YERDE BİLEREK 4'TE BIRAKTIM, çift saymamak için:
//   1814-09-18 Kongre'nin AÇILIŞI (çapa Nihaî Sened'e verildi)
//   1914-06-28 Saraybosna suikastı (çapa savaş İLANINA verildi)
//   Bu bir ölçüm değil bir TERCİH; koordinatör tersini derse değiştiririm.
//
// ── KAYNAK (§4) — ve bir DÜRÜSTLÜK BEYANI ────────────────────────────
// OKUNAN kaynaklar (gövdesi bu oturumda gerçekten açıldı):
//   TDV `avusturya` (200)  — Osmanlı-Habsburg cephesinin tamamı
//   TDV slug sınavı: canlı → avusturya · viyana · macaristan · karlofca ·
//     zenta · budin · belgrad · mohac · erdel · bosna-hersek ·
//     pasarofca-antlasmasi · zitvatorok-antlasmasi · vasvar-antlasmasi ·
//     estergon · egri · kanije · uyvar · temesvar · varadin
//     ÖLÜ (302) → pasarofca · zitvatorok · salzburg · prag · bohemya ·
//     silezya · metternich · franz-joseph · petervaradin · vasvar
//   Die Welt der Habsburger (habsburger.net / ww1.habsburger.net) —
//     Schloß Schönbrunn Kultur- und Betriebsges.m.b.H.'nin akademik
//     editörlü portali
//   Wien Geschichte Wiki (geschichtewiki.wien.gv.at) — Wiener Stadt- und
//     Landesarchiv'in kurumsal başvuru eseri
//   depo: `data/savaslar.js` — Osmanlı cephesinin gün hassasiyetli
//     tarihleri (proje içinde daha önce doğrulanmış)
//
// 🔴 OKUMADIĞIM HİÇBİR ESERE ATIF YAZMADIM. Gününü kaynaktan
//    doğrulayamadığım maddelerde `kaynak:` alanı bunu AÇIKÇA söyler
//    ("gün DOĞRULANMADI"). Sayısı raporda verildi. `§4`: kaynağı
//    yazılmayan bilgi, kaynağı olmayan bilgiden ayırt edilemez —
//    uydurma atıf ise ikisinden de kötüdür.
//
// ── MEVCUT 14 MADDENİN DENETİMİ ──────────────────────────────────────
// 14'ü de içeri alındı. Sekizinin tarihi bağımsız kaynakla DOĞRULANDI
// (1526-08-29 · 1529-09-27 · 1606-11-11 · 1683-09-12 · 1699-01-26 ·
//  1718-07-21 · 1739-09-18 · 1804-08-11). Altısının GÜNÜ bu oturumda
// doğrulanamadı (1541-08-29 · 1867-03-30 · 1878-07-13 · 1908-10-06 ·
//  1914-07-28 · 1918-11-11) — tarihleri DEĞİŞTİRİLMEDİ, damgalandı.
// ⚠️ Bir madde de ifade olarak düzeltildi: 1683 için künye "dönüm
//    noktası" diyordu ve doğru, ama Avusturya anlatısında dönüm 1683
//    değil 1683'ü izleyen FETİH ON YILIDIR (Budin 1686 · Harşan 1687 ·
//    Zenta 1697); ikisi ayrı maddeye bölündü.
// =====================================================================

