/* ==== data/kronoloji_lehistan.js ==== */
// =====================================================================
// LEHİSTAN — LİTVANYA (Rzeczpospolita) KRONOLOJİSİ
// Oturum: LEHİSTAN KRONOLOJİ · 20 Ağustos 2026
//
// Emre'nin ölçüsü: "o devletlerin muteber akademik kaynaklarını
// karıştırarak, O DEVLETİN O MİLLETİN ÖNEM VERDİĞİ ŞEKİLDE."
//
// ─────────────────────────────────────────────────────────────────────
// §D — İKİ PUAN (M-0873, KESİN ŞEMA · 20 Ağustos 2026)
//   onem  1-5   BU DOSYANIN DEVLETİ (Lehistan) için ağırlık.
//               Ölçüt: bu olay POLONYA tarihinin akışını ne kadar değiştirdi?
//               Dosyadan dosyaya DEĞİŞİR — kusur değil, tasarım.
//   dunya 1-5   OLAYIN kendisine ait. Ölçüt: devletler sistemini ne kadar
//               değiştirdi? Aynı olay HER dosyada AYNI `dunya` taşımalı.
//
// 🔴 İKİSİ DE İYİLİK/KÖTÜLÜK SKALASI DEĞİLDİR. Emre: "Osmanlı için kötü
//    bir olay diye gidip 1 veremezsin." Soru "iyi mi kötü mü" değil,
//    "tarihin akışını ne kadar değiştirdi".
//    ⇒ Bu dosyada 36 `onem:5` maddesinin 19'u POLONYA İÇİN FELAKETTİR
//      (1308 Gdańsk · 1444 Varna · 1654 Pereyaslav · 1655 Potop ·
//       1657 Wehlau · 1667 Andrusovo · 1672 Kamaniçe · 1717 Sessiz Sejm ·
//       üç taksim · 1792 Targowica · bastırılan ayaklanmalar).
//      Yani puanlar iyi/kötü ekseniyle verilmedi; ölçüldü ve DÜZELTİLECEK
//      kayıt ÇIKMADI (0).
//
// ⚠️ `dunya:5` YALNIZ ÜÇ MADDEDE var ve üçü de M-0873'ün kendi ölçeğinden:
//    1543 Kopernik (çağ açan) · 1683 Viyana · 1815 Viyana Kongresi.
//    Taksimler M-0873'ün örnek tablosuna uyularak `dunya:4` tutuldu —
//    üçüncü taksim devleti bitirse de AİLE TUTARLILIĞI korundu.
//
// 🟡 `olay_id` YOK. KAFKAS KRONOLOJİ (M-0878) bunu ölçüyle önerdi
//    (başlıkla eşleştirme 23/23 kaçırıyor, tarihle eşleştirme 6 sahte
//    ihlal üretiyor). Koordinatörün BİÇİM HÜKMÜ gelmeden tek taraflı
//    yazmadım — yazsaydım öteki dosyalarla ayrışma riski vardı.
//    Hüküm gelince eklenecek; bu dosyadaki paylaşılan olaylar raporda.
//
// ⇒ 1683 Viyana burada `onem:5`, Osmanlı kronolojisinde de `onem:5`
//    olmalıdır (ikisi için de dönüm noktası); ayrışan yalnız anlatıdır.
//
// ─────────────────────────────────────────────────────────────────────
// §K — KAYNAK POLİTİKASI (`CLAUDE.md §4`, KIRMIZI ÇİZGİ)
//
// İki cins `kaynak:` değeri var ve ikisi de MAKİNEYE SORULABİLİR:
//
//  ① TDV SLUG'I (çıplak ad)  — HTTP koduyla VE gövdesi OKUNARAK
//     doğrulandı. Kullanılanlar, 20 Ağustos 2026 ölçümü:
//       polonya (200) · varna-muharebesi (200) · hotin (200) ·
//       kamanice (200) · karlofca (200) · kili (200) · akkirman (200) ·
//       kazaklar (200) · bogdan (200) · kirim (200) · ukrayna (200)
//     🔴 ÖLÜ ölçülenler (302) — KULLANILMADI: bucas · zuravno ·
//       sobieski · podolya · stefan-batory · cehrin · lipka ·
//       kirim-hanligi · hmelnitski · prut · bahcesaray-antlasmasi ·
//       viyana-kusatmasi · ii-viyana-kusatmasi · lehistan-veraset-savasi
//     ⚠️ VE İKİ TUZAK ÖLÇÜLDÜ:
//       `lehistan` 200 döndürür ama gövdesi TEK SATIR: "bk. POLONYA"
//          → ÇAPRAZ GÖNDERME STUB'I. Asıl madde `polonya`.
//       `karlofca-antlasmasi` ARAMA SAYFASINA düşer; canlı olan `karlofca`.
//     📌 `bucas` ve `zuravno` slugları ölü AMA antlaşmaların tarihleri
//        `polonya` ve `kamanice` gövdelerinde VAR ⇒ "bulunamadı"
//        YAZILMADI, çünkü bulundu — yalnız başka adreste.
//
//  ② "el-kitabi"  — TDV'nin KAPSAMADIĞI Polonya İÇ tarihi (`§4`nin
