  d:"Erdel voyvodası Istvan Bathory, Osmanlı'nın siyasî ve askerî desteğiyle seçildi ve Jagiellon soyundan Anna ile evlenerek tahta oturdu. Polonya anlatısında güçlü ve muzaffer bir kral olarak anılır; aynı zamanda Osmanlı'nın Polonya kral seçimine doğrudan ağırlık koyduğu dönemin en açık örneğidir.",
