// -*- coding: utf-8 -*-
// KRONOLOJI_IRAN — İran'ın kendi tarihyazımının ölçüsüyle BİRLEŞİK kronoloji
// ---------------------------------------------------------------------------
// Koordinatör kararı (M-0876 sonrası brifing): `data/devletler.js`te İran
// ayrı künyelerde duruyor (ilhanli · celayirli · timurlu · karakoyunlu ·
// akkoyunlu · safevi · afsar · zend · kacar) ama kullanıcı "İran'ı seçip
// kronolojisini göreyim" dediğinde sekiz ayrı künye seçmek istemeyecek.
// ⇒ TEK dosyada 1281-1923 birleşik kronoloji; HER maddede hangi hânedan
// olduğu `d:` metninin İÇİNDE açıkça belirtilir (⚠️ ayrı bir `hanedan:`
// alanı YOK — brifingde istenmedi, gerekirse sonradan eklenir).
//
// ŞEMA (tahta M-0873, kesin hâl — Rusya dosyasıyla BİREBİR aynı):
//   { t, b, tur, onem:1-5 (BU dosyanın devleti — İran — için ağırlık),
//     dunya:1-5 (OLAYIN kendisine ait, HER dosyada AYNI olmalı),
//     kapsam:"ic"|"dis", etiket:[...], d:"...", kaynak:"..." }
// İkisi de iyilik/kötülük skalası DEĞİL — soru "tarihin akışını ne kadar
// değiştirdi?". `dunya:5` yalnız M-0873'ün kendi örnek kümesiyle (1453 ·
// 1492 · 1648 Vestfalya · 1683 Viyana · 1789 · 1815 · 1914) aynı düzeydeki
// olaylara verildi — Çaldıran gibi İran için `onem:5` olan bir yenilgi bile
// `dunya` ekseninde bölgesel kalabilir (M-0873'ün kendi örneği tam bu).
//
// TAKVİM: İran'da güneş yılı (Celâlî/Hicrî Şemsî) takvimi kullanılıyordu;
// bu dosyadaki `t:` alanları GREGORYEN'e çevrilmiş standart akademik
// tarihlerdir. Gün bilinmiyorsa YYYY-01-01.
//
// KAYNAK DİSİPLİNİ (CLAUDE.md §4):
//   Bu projede DAHA ÖNCE doğrulanmış ve data/olaylar*.js + data/savaslar.js +
//   data/devletler.js içinde kaynak: olarak KULLANILAN sluglar tekrar
//   sınanmadan alındı ("zaten doğrulanmış slug kümesi güvenlidir"):
//     amasya-antlasmasi · azerbaycan · caldiran-savasi · ferhad-pasa-antlasmasi
//     (⚠️ TDV'de MÜSTAKİL maddesi yok, hükümleri "luristan" maddesinden
//     toplanıyor — CLAUDE.md §4'te zaten belgeli) · kacarlar ·
//     kasrisirin-antlasmasi (14 Eyl 2026 düzeltildi; kasr-i-sirin-antlasmasi 302 ÖLÜ) · luristan · nadir-sah--iran · safeviler ·
//     sirvan · tebriz · akkoyunlular · celayirliler · ilhanlilar ·
//     karakoyunlular · mesrutiyet · timur · turkmenler.
//   Bu turda AYRICA sınandı (HTTP + içerik OKUNDU, 2026-08-20) ve BULGU:
//     gulistan-antlasmasi · turkmencay-antlasmasi → HTTP 200 ama İKİSİ DE
//     ARAMA SAYFASI (madde değil) — CLAUDE.md §4③ tuzağının yeni örneği.
//     Türkmençay'ın arama parçacığından doğrulanan tek gerçek: "10 Şubat
//     1828 ... İran, Erivan ve Nahcıvan'ı kaybetti" (azerbaycan/revan
//     maddelerinden derleniyor). Bu iki antlaşma TDV'nin zaten doğrulanmış
//     `azerbaycan` maddesi + akademik referansla kaynaklandı, TEK BAŞINA
//     slug UYDURULMADI.
//   TDV'nin KAPSAMADIĞI/tanecikli kapsamadığı iç Safevî-Kaçar tarihi için
//   standart akademik referans (CLAUDE.md §4, brifingin de KABUL ettiği):
//     Encyclopaedia Iranica (Columbia University, ed. Ehsan Yarshater) —
//       bu dosyanın omurga kaynağı, İran tarihi için standart akademik
//       ansiklopedi.
//     The Cambridge History of Iran, c.6 (Timurid-Safavid) ve c.7 (Qajar) —
//       standart ders kitabı serisi.
//   İkisi de kitap/ansiklopedi, tek tek URL doğrulanmadı (CLAUDE.md §4
//   "üniversite yayını" kategorisi, slug sınavı gerekmiyor). Hiçbir olgu
//   tartışmalı değildi, "bulunamadı" hiç kullanılmadı.
// ---------------------------------------------------------------------------
